package ru.metro.objmodels.client;
import java.io.File;import javax.imageio.ImageIO;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.vertex.DefaultVertexFormats;import net.minecraft.util.ResourceLocation;import net.minecraft.util.math.AxisAlignedBB;import org.lwjgl.opengl.GL11;import ru.metro.objmodels.ObjModels;import ru.metro.objmodels.common.*;
public class RenderPlacedModel extends Render<PlacedModelEntity>{
 public RenderPlacedModel(RenderManager m){super(m);}
 @Override protected ResourceLocation getEntityTexture(PlacedModelEntity e){return new ResourceLocation(ObjModels.MODID,"textures/blank.png");}
 @Override public void doRender(PlacedModelEntity e,double x,double y,double z,float yaw,float partial){ObjMesh m=ObjModelsRegistry.mesh(e.getModel());if(m==null)return;super.bindTexture(getEntityTexture(e));try{File f=ObjModelsRegistry.texture(e.getModel());if(f.isFile()){ResourceLocation r=new ResourceLocation(ObjModels.MODID,"runtime/"+e.getModel());if(!MinecraftTextures.has(r))MinecraftTextures.load(r,f);bindTexture(r);}}catch(Exception ignored){}
 GlStateManager.pushMatrix();GlStateManager.translate(x,y,z);GlStateManager.rotate(e.getRotation(),0,1,0);AxisAlignedBB b=m.bounds();double sx=b.maxX-b.minX,sy=b.maxY-b.minY,sz=b.maxZ-b.minZ;double scale=1.0/Math.max(1,Math.max(sx,Math.max(sy,sz)));GlStateManager.scale(scale,scale,scale);GlStateManager.translate(-(b.minX+b.maxX)/2,-b.minY,-(b.minZ+b.maxZ)/2);GlStateManager.disableCull();GlStateManager.enableTexture2D();Tessellator t=Tessellator.getInstance();BufferBuilder bb=t.getBuffer();bb.begin(GL11.GL_TRIANGLES,DefaultVertexFormats.POSITION_TEX);for(ObjMesh.Face face:m.faces)for(int i=1;i<face.v.length-1;i++){vertex(bb,m,face,0);vertex(bb,m,face,i);vertex(bb,m,face,i+1);}t.draw();GlStateManager.enableCull();GlStateManager.popMatrix();}
 private void vertex(BufferBuilder b,ObjMesh m,ObjMesh.Face f,int i){float[]v=m.vertices.get(f.v[i]);float[]uv=f.t[i]>=0&&f.t[i]<m.uvs.size()?m.uvs.get(f.t[i]):new float[]{0,0};b.pos(v[0],v[1],v[2]).tex(uv[0],uv[1]).endVertex();}
}
